import{_ as t,o,c as a,ag as r}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Conditional Formatting","description":"","frontmatter":{},"headers":[],"relativePath":"sheets/conditional-formatting.md","filePath":"sheets/conditional-formatting.md"}'),n={name:"sheets/conditional-formatting.md"};function s(l,e,i,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="conditional-formatting" tabindex="-1">Conditional Formatting <a class="header-anchor" href="#conditional-formatting" aria-label="Permalink to &quot;Conditional Formatting&quot;">​</a></h1><p>Conditional formatting paints cells based on what they contain. A rule watches a range, and every cell in that range whose value matches the rule&#39;s condition picks up the rule&#39;s bold / italic / underline / colors.</p><p>The formatting is applied at paint time — it never changes the value in the cell and never overwrites the formatting you applied by hand. Delete the rule and the cells go straight back to how they looked.</p><h2 id="open-the-conditional-formatting-panel" tabindex="-1">Open the Conditional Formatting Panel <a class="header-anchor" href="#open-the-conditional-formatting-panel" aria-label="Permalink to &quot;Open the Conditional Formatting Panel&quot;">​</a></h2><p>Click the <strong>Conditional formatting</strong> (brush) icon in the toolbar to open the right-side panel.</p><p>On a narrow screen the toolbar collapses its extra tools into a <strong>More formatting options</strong> (⋮) menu — open it and choose <strong>Conditional formatting</strong> there.</p><p>There is no right-click entry for conditional formatting, and the panel is only available on regular sheet tabs. See <a href="#where-rules-live">Where rules live</a> for the tabs it does not cover.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Select the cells you want to format <strong>before</strong> opening the panel. Clicking back into the grid closes the panel, so the selection you had when you opened it is the one the panel can use.</p></div><h2 id="add-a-rule" tabindex="-1">Add a Rule <a class="header-anchor" href="#add-a-rule" aria-label="Permalink to &quot;Add a Rule&quot;">​</a></h2><ol><li>Select the range you want to format.</li><li>Open the panel and click <strong>Add</strong>.</li></ol><p>The new rule starts as <strong>Is not empty</strong> with a pale-yellow fill, scoped to the cells you had selected (or to <code>A1</code> if nothing was selected), and its editor opens below the rule list.</p><p>From there:</p><ul><li><strong>Apply to range</strong> — type a range and click <strong>Apply</strong>, or click <strong>Use selected range</strong> to fill it from your current grid selection.</li><li><strong>Format rules</strong> — pick the condition and its value (see below).</li><li><strong>Formatting style</strong> — pick what the matching cells should look like.</li></ul><h3 id="writing-ranges" tabindex="-1">Writing ranges <a class="header-anchor" href="#writing-ranges" aria-label="Permalink to &quot;Writing ranges&quot;">​</a></h3><p>The range box takes A1 ranges with <strong>both ends written out</strong>, separated by commas for a rule that covers several blocks:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A1:B10, D1:E10</span></span></code></pre></div><p>A single cell has to be written as <code>A1:A1</code> — a bare <code>A1</code> is rejected with <em>&quot;Enter valid A1 ranges like A1:D20 or A1:B10, D1:E10.&quot;</em></p><p><strong>Use selected range</strong> needs a cell selection. If you have a whole row, a whole column, or the entire sheet selected via its header, it answers <em>&quot;Select a cell range first.&quot;</em></p><h2 id="format-rules" tabindex="-1">Format Rules <a class="header-anchor" href="#format-rules" aria-label="Permalink to &quot;Format Rules&quot;">​</a></h2><p>The <strong>Format rules</strong> dropdown offers seven conditions:</p><table tabindex="0"><thead><tr><th>Condition</th><th>What it matches</th></tr></thead><tbody><tr><td>Is empty</td><td>The cell is blank (or holds only whitespace)</td></tr><tr><td>Is not empty</td><td>The cell holds anything else</td></tr><tr><td>Text contains</td><td>The cell&#39;s text contains what you typed, ignoring case</td></tr><tr><td>Greater than</td><td>The cell is a number greater than the number you typed</td></tr><tr><td>Is between</td><td>The cell is a number inside the two bounds, inclusive</td></tr><tr><td>Date before</td><td>The cell is a date earlier than the date you typed</td></tr><tr><td>Date after</td><td>The cell is a date later than the date you typed</td></tr></tbody></table><p><strong>Is empty</strong> and <strong>Is not empty</strong> take no value. <strong>Is between</strong> shows two boxes, <strong>Min</strong> and <strong>Max</strong> — the range is inclusive at both ends, and entering them in the wrong order still works. The other four show a single box, prompting <em>Enter text</em>, <em>Enter number</em>, or <em>YYYY-MM-DD</em> depending on the condition.</p><p>A few details worth knowing:</p><ul><li><strong>Greater than</strong> and <strong>Is between</strong> compare numbers. Thousands separators in the cell or in the value you type are ignored, and a cell that isn&#39;t a number simply never matches.</li><li><strong>Date before</strong> / <strong>Date after</strong> compare whole days. <code>YYYY-MM-DD</code> is the format the box asks for; other date text is accepted if the browser can read it, and a cell that isn&#39;t a date never matches.</li></ul><h2 id="formatting-style" tabindex="-1">Formatting Style <a class="header-anchor" href="#formatting-style" aria-label="Permalink to &quot;Formatting Style&quot;">​</a></h2><p>A rule can set any combination of:</p><ul><li><strong>Bold</strong>, <strong>Italic</strong>, <strong>Underline</strong> toggles</li><li><strong>Text color</strong> — a palette, plus <strong>Reset</strong> to go back to the default color</li><li><strong>Background color</strong> — a palette, plus <strong>None</strong> for no fill</li></ul><p>That&#39;s the whole list. A rule can&#39;t change number formats, borders, fonts, or alignment.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A rule is only saved once it is complete. A rule with <strong>no</strong> style at all — every toggle off and both colors cleared — is dropped, and so is a value-taking rule whose value box is still empty. It disappears from the panel the next time you open it.</p></div><h2 id="rule-order-and-overlap" tabindex="-1">Rule Order and Overlap <a class="header-anchor" href="#rule-order-and-overlap" aria-label="Permalink to &quot;Rule Order and Overlap&quot;">​</a></h2><p>The panel says it at the top: <strong>rules are applied from top to bottom</strong>. Each rule card is numbered, and the ↑ / ↓ buttons on a card move it in that order.</p><p>When two rules match the same cell, their styles are <strong>merged</strong>, and the rule lower in the list wins for the properties it actually sets. A rule that only sets a background color leaves an earlier rule&#39;s bold and text color in place; a rule that also sets a background color replaces the earlier one&#39;s.</p><p>Conditional formatting sits on top of every other style layer — sheet, column, row, range, and the cell&#39;s own formatting. Where a rule matches, its properties win.</p><h2 id="edit-or-delete-a-rule" tabindex="-1">Edit or Delete a Rule <a class="header-anchor" href="#edit-or-delete-a-rule" aria-label="Permalink to &quot;Edit or Delete a Rule&quot;">​</a></h2><ul><li>Click a rule&#39;s card to select it; its range, condition, and style appear in the editor below.</li><li>Click the <strong>✕</strong> on a card to delete the rule. The formatting for that range disappears immediately.</li></ul><p>Each card also summarizes itself — the condition and value, the ranges it covers, swatches for its colors, and a short style summary such as <code>B · Fill</code> (or <code>No style</code>).</p><h2 id="rules-and-structural-edits" tabindex="-1">Rules and Structural Edits <a class="header-anchor" href="#rules-and-structural-edits" aria-label="Permalink to &quot;Rules and Structural Edits&quot;">​</a></h2><p>Rules follow the grid. Inserting, deleting, or moving rows and columns remaps every rule&#39;s ranges to match, so a rule on <code>B2:B100</code> still covers the same cells after a row is inserted above it.</p><p>If a rule&#39;s ranges are deleted entirely — you delete every row or column it covered — the rule is removed with them.</p><h2 id="where-rules-live" tabindex="-1">Where Rules Live <a class="header-anchor" href="#where-rules-live" aria-label="Permalink to &quot;Where Rules Live&quot;">​</a></h2><p>Rules belong to a <strong>single tab</strong> and are saved into the document, so collaborators see the same formatting you do. A person opening the document through a read-only share link sees the formatting too; they just don&#39;t get the panel.</p><ul><li><strong>Sheet tabs</strong> — fully supported.</li><li><strong>Pivot table tabs</strong> — supported; they&#39;re sheet tabs, and refreshing a pivot rewrites its cells without touching the rules. But a rule stays anchored to the cells you gave it, so a pivot that changes shape can leave a rule covering the wrong part of the output.</li><li><strong>DataSource and Lakehouse tabs</strong> — not supported. Those tabs render a read-only result grid with no formatting toolbar, so there&#39;s no way to open the panel on them. Shape the data in SQL instead, or copy the results into a sheet tab and format it there.</li></ul>',42)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
